{
  "description": "The creature is shown in right-facing profile standing on a small patch of ground against a plain off-white background. It has a low, arched quadrupedal body that is mostly covered dorsally in overlapping brown scales, with a pale pinkish-tan smooth-skinned head at the front bearing a blunt rounded snout and large dark eyes, six pink feathery external gills protruding from the neck just behind the head, four stout legs with scaly upper surfaces and pale wrinkled lower surfaces ending in clawed feet on the ground, and a thick tapering scaly tail extending to the left rear. The ventral area between the fore and hind legs shows pale, wrinkled, unscaled skin.",
  "parts": [
    {
      "part": "head",
      "looks_like": "pale pinkish-tan smooth skin with a blunt rounded snout, small nostril opening, and a large dark eye with a pale blue-grey iris and black pupil",
      "where": "at the front right end of the body, with the top of the head capped by small overlapping brown scales"
    },
    {
      "part": "gills",
      "looks_like": "six pink feathery external gills with many fine filamentous branches along a central stalk, fleshy at the base and feathery toward the tip",
      "where": "three protruding from each side of the neck directly behind the head, curving outward and upward"
    },
    {
      "part": "scales",
      "looks_like": "numerous overlapping keratinous scales, brown with darker centers and lighter tan edges, glossy, larger and more rounded on the back and sides, smaller on the crown of the head and upper legs",
      "where": "covering the dorsal back, sides, top of head, tail, and upper portions of all four legs"
    },
    {
      "part": "legs",
      "looks_like": "four thick stout legs, scaly on the outer and upper surfaces, pale wrinkled skin on the inner and lower surfaces",
      "where": "beneath the body, two forelegs under the chest and two hindlegs under the mid-body, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad pale feet with distinct toes and dark brown to black curved claws, about four to five claws visible per foot",
      "where": "at the distal ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick tapering tail covered in the same overlapping brown scales as the back",
      "where": "at the left rear of the body, extending leftward and slightly out of view"
    },
    {
      "part": "markings",
      "looks_like": "pale off-white to cream wrinkled skin without scales, with faint horizontal folds",
      "where": "on the ventral underside between the fore and hind legs and on the inner lower portions of the legs"
    }
  ],
  "attached_objects": [],
  "animals": ["pangolin", "axolotl"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
